package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public final class CityTestsRural {
 static RuralRules.Person person(){var p=new RuralRules.Person();p.id=UUID.randomUUID();return p;}
 static RuralRules.Family family(RuralRules.Person p){var f=new RuralRules.Family();f.id=UUID.randomUUID();f.city=UUID.randomUUID();f.members.add(p.id);p.family=f.id;return f;}
 @GameTest(template="empty") public static void famineFifteenMealsAndRecovery(GameTestHelper h){var p=person();for(int i=0;i<4;i++)RuralRules.meal(List.of(p),List.of());h.assertTrue(p.hunger()==0,"Four missed meals not first threshold");RuralRules.meal(List.of(p),List.of());h.assertTrue(p.hunger()==1,"Fifth meal first threshold");for(int i=0;i<5;i++)RuralRules.meal(List.of(p),List.of());h.assertTrue(p.hunger()==2,"Tenth extreme hunger");for(int i=0;i<5;i++)RuralRules.meal(List.of(p),List.of());h.assertTrue(p.dead,"Exactly fifteen meals=7.5 hours");var child=person();child.age=RuralRules.Age.CHILD;child.nourishment=15;for(int i=0;i<15;i++)RuralRules.meal(List.of(child),List.of());h.assertTrue(child.dead,"Child loses percentage not adult fixed amount");var mother=person();mother.pregnant=true;mother.infants=2;mother.nourishment=mother.maximum();h.assertTrue(mother.meal()==5&&mother.maximum()==75,"Pregnancy and two dependents stack on one caregiver");h.succeed();}
 @GameTest(template="empty") public static void reservesTradeAndNoMint(GameTestHelper h){var farmer=person();var head=person();var f=family(farmer);var m=family(head);var a=new RuralRules.Stock();a.wheat=10;var b=new RuralRules.Stock();Map<UUID,Long> money=new HashMap<>(Map.of(farmer.id,50L,head.id,50L));int harvested=RuralRules.harvest(List.of(a),4,m,farmer.id,List.of(b),2,money);h.assertTrue(harvested==4&&a.wheat==10&&b.wheat==4,"Full private reserve retained; only new crop sold");h.assertTrue(money.get(head.id)==42&&money.get(farmer.id)==58,"Actual silver transferred");var c=new RuralRules.Stock();int bought=RuralRules.trade(f,head.id,List.of(b),List.of(c),false,99,3,money);h.assertTrue(bought==4&&money.values().stream().mapToLong(Long::longValue).sum()==100,"Bounded stock and conserved money");money.put(farmer.id,0L);h.assertTrue(RuralRules.trade(f,head.id,List.of(c),List.of(b),false,1,3,money)==0,"No free emergency purchasing");h.succeed();}
 @GameTest(template="empty") public static void cookingFamilyCapAndTraining(GameTestHelper h){var s=new RuralRules.Stock();s.wheat=10;h.assertTrue(RuralRules.cook(List.of(s),15,4,false)==4&&s.wheat==6&&s.bread==4,"Only family target cooked 1:1");h.assertTrue(RuralRules.cook(List.of(s),15,4,true)==0,"No extra baking when target already covered");h.assertTrue(RuralRules.efficiency(0)==.5&&RuralRules.efficiency(1)==.75&&RuralRules.efficiency(2)==.875&&RuralRules.efficiency(9)==1,"Hourly training curve");var map=new HashMap<UUID,RuralRules.Person>();var f=new RuralRules.Family();f.id=UUID.randomUUID();for(int i=0;i<9;i++){var p=person();map.put(p.id,p);RuralRules.admit(f,p,map);}map.get(f.members.getFirst()).pregnant=true;boolean rejected=false;try{RuralRules.admit(f,person(),map);}catch(IllegalArgumentException ex){rejected=true;}h.assertTrue(rejected&&f.members.size()==9,"Pregnancy reserves tenth place");h.succeed();}
 @GameTest(template="empty") public static void workBlocksAndPortableLink(GameTestHelper h){h.setBlock(1,2,1,RuralBlocks.CHEST.get());var box=(RuralBlocks.Link)h.getBlockEntity(new BlockPos(1,2,1));box.offset=new BlockPos(2,0,-1);var tag=box.saveWithFullMetadata(h.getLevel().registryAccess());h.assertTrue(tag.getIntArray("RuralWorkOffset").length==3&&!tag.contains("Worker")&&!tag.contains("Family"),"Blueprint carries relative configuration only");var restored=new RuralBlocks.Link(new BlockPos(9,2,9),RuralBlocks.CHEST.get().defaultBlockState());restored.loadWithComponents(tag,h.getLevel().registryAccess());h.assertTrue(restored.offset.equals(box.offset),"Relative link survives roundtrip");h.succeed();}
 @GameTest(template="empty") public static void ruralSaveReload(GameTestHelper h){var d=new RuralSettlement();var p=person();var f=family(p);d.state.people.put(p.id,p);d.state.families.put(f.id,f);p.nourishment=17;p.productionCredit=.75;var restored=RuralSettlement.load(d.save(new CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(restored.state.people.get(p.id).nourishment==17&&restored.state.people.get(p.id).productionCredit==.75,"Reload preserves deficits and fractional production");h.succeed();}
 @GameTest(template="empty") public static void caregiverChangesAndDeathReleaseCapacity(GameTestHelper h){var a=person();var b=person();var f=family(a);b.age=RuralRules.Age.INFANT;b.caregiver=a.id;b.family=f.id;f.members.add(b.id);a.nourishment=15;var people=new HashMap<UUID,RuralRules.Person>(Map.of(a.id,a,b.id,b));RuralRules.refreshCaregivers(people);h.assertTrue(a.meal()==3&&a.nourishment==22.5,"Caregiver demand changes without restoring percentage");b.dead=true;RuralRules.refreshCaregivers(people);h.assertTrue(a.meal()==2&&a.nourishment==15&&RuralRules.reserved(f,people)==1,"Dead dependent releases demand and population slot");h.succeed();}
}
